-- ============================================================
-- 028_ielts_vocabulary_words_800_999.sql
-- Content batch: IELTS Band 8 vocabulary words 800-999,
-- transcribed from "1000 Essential Words for Band 8" (word, part of
-- speech, definition, and example extracted from the source; Bangla
-- meanings authored fresh, since the PDF's own Bangla text layer is
-- corrupted at the font level -- see migration notes).
-- ============================================================

do $$
declare
  v_idiomatic_spoken_expressions uuid;
  v_speaking_fillers uuid;
  v_task_1_trend_and_data_language uuid;
  v_advanced_adjectives uuid;
  v_advanced_adverbs_of_degree uuid;
  v_academic_verbs uuid;
begin
  select cn.id into v_idiomatic_spoken_expressions from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'idiomatic-spoken-expressions';
  select cn.id into v_speaking_fillers from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'speaking-fillers';
  select cn.id into v_task_1_trend_and_data_language from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'task-1-trend-and-data-language';
  select cn.id into v_advanced_adjectives from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'advanced-adjectives';
  select cn.id into v_advanced_adverbs_of_degree from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'advanced-adverbs-of-degree';
  select cn.id into v_academic_verbs from content_nodes cn join content_nodes ielts_vocab on cn.parent_id = ielts_vocab.id join content_nodes ielts on ielts_vocab.parent_id = ielts.id where ielts.slug = 'ielts' and ielts_vocab.slug = 'vocabulary' and cn.slug = 'academic-verbs';

end $$;
